use avifenc_rust::{EncoderOptions, ImageBuffer, PixelInformation, Rgba16ImageBuffer};

// Frozen at 6a7ba0a using the portable u16 backend, not regenerated by this test.
// See performance/third-pass/ for source pins and the standalone generator.
#[test]
fn encoder_matches_portable_reference_bitstreams_at_all_depths() {
    eprintln!(
        "rav1e CPU dispatch: {:?}",
        rav1e::config::CpuFeatureLevel::default()
    );
    let (width, height) = (32, 24);
    let rgba: Vec<u8> = (0..width * height)
        .flat_map(|i| {
            let (x, y) = (i % width, i / width);
            [
                ((x * 7 + y * 3) % 256) as u8,
                ((x * 2 + y * 11) % 256) as u8,
                ((x ^ y) % 256) as u8,
                ((x * 5 + y * 7) % 256) as u8,
            ]
        })
        .collect();
    for (depth, expected) in [
        (8, include_bytes!("fixtures/portable-8bit.avif").as_slice()),
        (
            10,
            include_bytes!("fixtures/portable-10bit.avif").as_slice(),
        ),
        (
            12,
            include_bytes!("fixtures/portable-12bit.avif").as_slice(),
        ),
    ] {
        let options = EncoderOptions {
            quality: 60,
            quality_alpha: 60,
            speed: 10,
            jobs: 0,
            pixel_information: (depth != 8).then(|| PixelInformation {
                bits_per_channel: vec![depth; 3],
                extended_channels: None,
            }),
            ..Default::default()
        };
        let encoded = if depth == 8 {
            avifenc_rust::encode_bytes(
                &ImageBuffer {
                    width,
                    height,
                    rgba: rgba.clone(),
                },
                &options,
            )
            .unwrap()
        } else {
            avifenc_rust::encode_rgba16_bytes(
                &Rgba16ImageBuffer {
                    width,
                    height,
                    rgba: rgba.iter().map(|&v| u16::from(v) * 257).collect(),
                },
                &options,
            )
            .unwrap()
        };
        assert_eq!(
            encoded.as_slice(),
            expected,
            "{depth}-bit backend output changed"
        );
    }
}
